// @ts-expect-error Generated by the Cloudflare build; no declaration file is emitted.
import next from "./.open-next/worker.js";
import media from "./.generated/media-manifest.json";
import manifest from "./.generated/manifest.json";
import { serveMedia, type Media } from "./lib/worker-media";
import { notFoundResponse } from "./lib/not-found";

const pages = new Set(["/", "/fr", ...manifest.map((page) => page.url)]);
const redirects = new Map<string, string>();
for (const page of manifest) {
  if (!page.project) continue;
  const root = `${page.locale === "fr" ? "/fr" : ""}/${page.project}`;
  if (redirects.has(root)) continue;
  const first =
    manifest.find(
      (candidate) =>
        candidate.locale === page.locale &&
        candidate.project === page.project &&
        ["getting-started", "introduction"].includes(candidate.slug),
    ) || page;
  redirects.set(root, first.url);
}

export default {
  async fetch(
    request: Request,
    env: {
      ASSETS: { fetch(request: Request | string): Promise<Response> };
    },
    context: unknown,
  ) {
    const url = new URL(request.url);
    const pathname = url.pathname.replace(/\/+$/, "") || "/";
    if (pathname === "/zauctionhouse/multi-server" || pathname === "/fr/zauctionhouse/multi-server") {
      url.pathname = pathname.replace("/multi-server", "/addons/redis/introduction");
      return Response.redirect(url, 308);
    }
    if (pathname === "/en" || pathname.startsWith("/en/")) {
      url.pathname = pathname.slice(3) || "/";
      return Response.redirect(url, 308);
    }
    const redirect = redirects.get(pathname);
    if (redirect || (pathname !== url.pathname && pages.has(pathname))) {
      url.pathname = redirect || pathname;
      return Response.redirect(url, 308);
    }
    const entry = (media as Record<string, Media>)[
      new URL(request.url).pathname
    ];
    if (entry) return serveMedia(request, env.ASSETS, entry);
    // All documentation is pre-rendered from Git. Unknown paths must not load
    // the complete MDX renderer merely to produce a 404 in a constrained Worker.
    const documentPath = pathname.replace(/\.md$/, "");
    if (
      !pages.has(documentPath) &&
      ![
        "/api/search",
        "/api/mcp",
        "/api/markdown",
        "/api/discord",
        "/llms.txt",
        "/llms-full.txt",
        "/robots.txt",
        "/sitemap.xml",
      ].includes(pathname) &&
      !pathname.startsWith("/api/markdown/")
    ) {
      if (pathname.startsWith("/_next/") || /\.[^/]+$/.test(pathname)) {
        const asset = await env.ASSETS.fetch(request);
        if (asset.status !== 404) return asset;
      }
      return notFoundResponse(request);
    }
    return next.fetch(request, env, context);
  },
};
